#pragma once

// EspOS display fonts (generated by scripts/espos_fonts.py, registered in main.cpp).
// Sizes are points at the converter's 150 dpi: 24 pt ≈ 50 px, 44 pt ≈ 92 px on the X4 panel.
#define ESPOS_24_FONT_ID (0x494B3234)        // NotoSans Bold 24: titles, dates, flashcard word
#define ESPOS_44_FONT_ID (0x494B3434)        // NotoSans Bold 44, digits only: temperature, counters
#define ESPOS_60_FONT_ID (0x494B3630)        // NotoSans Bold 60 (~125 px), digits only: sleep-screen clock and day
#define ESPOS_SERIF_36_FONT_ID (0x494B5336)  // NotoSerif Bold 36, Vietnamese letters: word clock, headings
#define ESPOS_30_FONT_ID (0x494B3330)        // NotoSans Bold 30 (~62 px), digits only: sleep-screen temperature
